S = "Hakeem Force Academy"
QS = [
(S, "By what other name is Pakistan Day, observed on 23 March, also known?", ["Independence Day", "Republic Day", "Resolution Day (Lahore Resolution Day)", "Constitution Day"], 2,
 "Pakistan Day commemorates the Lahore Resolution (Pakistan Resolution) passed on 23 March 1940, so it is also called Resolution Day. It also marks the adoption of the first constitution in 1956.",
 "Pakistan became a republic on 23 March 1956 when its first constitution came into force.", [3085]),
(S, "Who described Quaid-e-Azam Muhammad Ali Jinnah as the Ambassador of Hindu-Muslim Unity?", ["Sarojini Naidu", "Allama Iqbal", "Maulana Muhammad Ali Jauhar", "Liaquat Ali Khan"], 0,
 "Sarojini Naidu gave Jinnah this title, praising his work for unity at the time of the 1916 Lucknow Pact. Her 1918 book on him is titled Mohomed Ali Jinnah: An Ambassador of Unity.",
 "Gopal Krishna Gokhale had earlier made a similar remark about Jinnah, so some sources trace the phrase to him.", [4847, 4855]),
(S, "Who was the first ambassador of Pakistan to the United States?", ["Mirza Abol Hassan Ispahani", "Syed Amjad Ali", "Muhammad Ali Bogra", "Aziz Ahmed"], 0,
 "Mirza Abol Hassan Ispahani, a close associate of Jinnah, was the first Pakistani ambassador to the USA. He served until 1952.",
 "Sources differ on whether he took up the post in 1947 or 1948; he later served as High Commissioner to Britain.", [172, 1314]),
(S, "In which year was the 18th Amendment to the 1973 Constitution of Pakistan passed?", ["2008", "2010", "2012", "2004"], 1,
 "The 18th Amendment was passed by Parliament in April 2010 and signed by President Zardari. It transferred many powers from the centre to the provinces.",
 "It renamed the North-West Frontier Province as Khyber Pakhtunkhwa and removed the President's power to dissolve the National Assembly under 58(2)(b).", [2385, 755, 756, 417]),
(S, "In which year did the United States declare its independence?", ["1783", "1789", "1766", "1776"], 3,
 "The Declaration of Independence was adopted on 4 July 1776. That is why 4 July is celebrated as American Independence Day.",
 "In July 2026 the United States marked 250 years since its Declaration of Independence.", [2391]),
(S, "Who was the first woman Speaker of the United States House of Representatives?", ["Hillary Clinton", "Kamala Harris", "Condoleezza Rice", "Nancy Pelosi"], 3,
 "Nancy Pelosi of California became the first woman Speaker of the US House in January 2007. She held the post again from 2019 to 2023.",
 "Pelosi was succeeded as Speaker by Kevin McCarthy in 2023, and later by Mike Johnson.", [5096, 1255]),
(S, "In which surah of the Holy Quran is Ruh-ul-Amin (the Trustworthy Spirit, Hazrat Jibreel AS) mentioned?", ["Surah Al-Baqarah", "Surah Ash-Shu'ara", "Surah Maryam", "Surah Al-Qadr"], 1,
 "Surah Ash-Shu'ara (26:193) says that the Trustworthy Spirit brought down the Quran upon the heart of the Prophet (PBUH). The Trustworthy Spirit is Hazrat Jibreel (AS).",
 "Jibreel is also called Ruh-ul-Qudus in other verses, for example in Surah Al-Baqarah.", [428]),
(S, "In what amount was the valley of Kashmir sold to Gulab Singh under the Treaty of Amritsar (1846)?", ["75 lakh Nanakshahi rupees", "10 lakh rupees", "1 crore rupees", "25 lakh rupees"], 0,
 "By the Treaty of Amritsar the British sold Kashmir to Gulab Singh Dogra for 75 lakh Nanakshahi rupees. This began Dogra rule in Kashmir.",
 "The treaty was signed on 16 March 1846 after the First Anglo-Sikh War.", [2145]),
(S, "Who is the angel of death (Malak-ul-Maut) in Islamic belief?", ["Hazrat Jibreel (AS)", "Hazrat Mikail (AS)", "Hazrat Izrail (AS)", "Hazrat Israfil (AS)"], 2,
 "Hazrat Izrail (AS) is the angel entrusted with taking souls at death. The Quran refers to him as the angel of death in Surah As-Sajdah.",
 "Hazrat Israfil (AS) is the angel who will blow the trumpet on the Day of Judgement.", [4905]),
(S, "Two adjacent angles which together form a right angle are called what?", ["Supplementary angles", "Complementary angles", "Vertical angles", "Reflex angles"], 1,
 "Two angles whose sum is 90 degrees are complementary. Together they make one right angle.",
 "Supplementary angles add up to 180 degrees, which is a straight line.", [2808]),
(S, "What is the closest meaning of the word annihilate?", ["Destroy completely", "Praise", "Invite", "Repair"], 0,
 "To annihilate is to destroy something utterly so that nothing remains. Its closest meaning is to destroy completely.",
 "The word comes from the Latin annihilare, meaning to reduce to nothing.", [3255, 3719]),
(S, "What is the antonym of the word sumptuous?", ["Lavish", "Splendid", "Meagre", "Rich"], 2,
 "Sumptuous means grand and expensive-looking, so its opposite is meagre or poor. Lavish, splendid and rich are synonyms.",
 "Sumptuous is often used for meals, such as a sumptuous feast.", [631]),
(S, "What is the antonym of the word abolish?", ["Cancel", "Establish", "Remove", "End"], 1,
 "To abolish is to put an end to something officially. Its opposite is to establish, meaning to set up.",
 "Abolish, cancel, remove and end are all close in meaning to each other.", [3129]),
(S, "What is the antonym of the word accumulated?", ["Gathered", "Collected", "Piled", "Dispersed"], 3,
 "Accumulated means gathered together over time. The opposite is dispersed, meaning scattered.",
 "Accumulate is a synonym of amass and collect.", [3131]),
(S, "What is the antonym of the word Almighty?", ["Powerless", "Supreme", "Omnipotent", "Mighty"], 0,
 "Almighty means having unlimited power. Its opposite is powerless or weak.",
 "Almighty is used for God in Islam and in many other religions.", [893]),
(S, "What is the antonym of the word amalgamate?", ["Merge", "Unite", "Separate", "Combine"], 2,
 "To amalgamate means to merge or combine into one. The opposite is to separate.",
 "Amalgam is also the name of an alloy of mercury with another metal.", [461]),
(S, "Find the missing number in the analogy 2 : X :: 4 : 16.", ["3", "8", "6", "4"], 3,
 "Since 4 : 16 shows that 16 is the square of 4 (4 x 4 = 16), the same rule applies to 2, so X = 2 x 2 = 4.",
 "Square numbers are 1, 4, 9, 16, 25 and so on.", [2864]),
(S, "Anemia is mainly caused by the deficiency of which element?", ["Calcium", "Iodine", "Sodium", "Iron"], 3,
 "Iron is needed to make haemoglobin in red blood cells. Without enough iron the blood cannot carry enough oxygen, which causes anemia.",
 "Iodine deficiency causes goitre.", [1491]),
(S, "Area of a parallelogram = base x ______.", ["altitude (height)", "diagonal", "perimeter", "side"], 0,
 "The area of a parallelogram is its base multiplied by its perpendicular height, also called its altitude.",
 "The area of a triangle is half of base times altitude.", [1499]),
(S, "Amjad and Ahmad kept 24 balls in all. Amjad kept 3 times as many as Ahmad. How many did Ahmad keep?", ["8", "4", "6", "12"], 2,
 "Let Ahmad have x balls, so Amjad has 3x. Then x + 3x = 24, so 4x = 24 and x = 6.",
 "Amjad therefore kept 18 balls.", [630]),
(S, "Razaq is 4 years old and Amjad is twice as old as Razaq. When Razaq is 12 years old, how old will Amjad be?", ["24", "20", "16", "18"], 2,
 "Amjad is now 2 x 4 = 8, so he is 4 years older than Razaq. When Razaq is 12, Amjad will be 12 + 4 = 16.",
 "The difference in their ages stays the same all the time.", [277]),
]
